#' Uncertainties from homogeneity
#'
#' 
#' @param data .
#' @param x .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$ufh} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$xm} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$n} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$msbb} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$mswb} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
UFH <- function(
    data,
    x) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("UFH requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- UFHOptions$new(
        x = x)

    analysis <- UFHClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

